CREATE OR REPLACE FUNCTION public.notify_payout_account_operational_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_type text;
begin
  if coalesce(old.verification_status, '') = coalesce(new.verification_status, '')
    or new.verification_status not in ('verified', 'rejected')
  then
    return new;
  end if;

  v_type := case
    when new.verification_status = 'verified' then 'payout_account_approved'
    else 'payout_account_rejected'
  end;

  perform public.create_operational_notification(
    new.traveler_user_id,
    v_type,
    case when new.verification_status = 'verified' then 'Cuenta de retiro aprobada' else 'Cuenta de retiro rechazada' end,
    case when new.verification_status = 'verified' then 'Tu cuenta de retiro fue aprobada.' else 'Tu cuenta de retiro fue rechazada.' end,
    null,
    'payout_account:' || new.id::text || ':' || new.verification_status,
    true
  );

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_match_read(p_match_id uuid, p_read_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_owner_id uuid;
  v_traveler_id uuid;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'not_authenticated');
  end if;

  select s.owner_id, t.traveler_id
  into v_owner_id, v_traveler_id
  from public.matches m
  join public.shipments s on s.id = m.shipment_id
  join public.trips t on t.id = m.trip_id
  where m.id = p_match_id;

  if v_owner_id is null then
    return jsonb_build_object('success', false, 'error', 'match_not_found');
  end if;

  if v_actor = v_owner_id then
    update public.matches set last_read_by_owner = p_read_at where id = p_match_id;
  elsif v_actor = v_traveler_id then
    update public.matches set last_read_by_traveler = p_read_at where id = p_match_id;
  else
    return jsonb_build_object('success', false, 'error', 'not_authorized');
  end if;

  return jsonb_build_object('success', true, 'read_at', p_read_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.request_payout(p_amount numeric, p_payout_account_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text, p_payment_policy_accepted boolean DEFAULT false, p_payment_policy_version text DEFAULT '1.0'::text, p_payment_policy_acceptance_flow text DEFAULT 'wallet_payout_request'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_wallet public.wallets;
  v_config public.fee_configs;
  v_account public.traveler_payout_accounts;
  v_selected_account_id uuid;
  v_reserved_amount numeric := 0;
  v_withdrawable numeric := 0;
  v_verification public.user_verifications;
  v_payout_id uuid;
  v_accepted_at timestamptz := now();
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'not_authenticated');
  end if;

  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'invalid_amount');
  end if;

  if coalesce(p_payment_policy_accepted, false) = false then
    return jsonb_build_object('success', false, 'error', 'payment_policy_required');
  end if;

  if nullif(btrim(coalesce(p_payment_policy_version, '')), '') is null then
    return jsonb_build_object('success', false, 'error', 'invalid_payment_policy_version');
  end if;

  select *
  into v_verification
  from public.user_verifications uv
  where uv.user_id = v_actor
  limit 1;

  if coalesce(v_verification.verification_level, 'basic_verified') <> 'payout_verified' then
    return jsonb_build_object('success', false, 'error', 'payout_verification_required');
  end if;

  select *
  into v_config
  from public.fee_configs
  where is_active = true
  order by updated_at desc, created_at desc
  limit 1;

  if p_amount < coalesce(v_config.minimum_payout_cop, 10000) then
    return jsonb_build_object(
      'success', false,
      'error', 'below_minimum_payout',
      'minimum_payout', coalesce(v_config.minimum_payout_cop, 10000)
    );
  end if;

  select *
  into v_wallet
  from public.wallets
  where user_id = v_actor
  for update;

  if v_wallet.id is null then
    return jsonb_build_object('success', false, 'error', 'wallet_not_found');
  end if;

  v_selected_account_id := p_payout_account_id;

  if v_selected_account_id is null then
    select id
    into v_selected_account_id
    from public.traveler_payout_accounts
    where traveler_user_id = v_actor
      and verification_status = 'verified'
    order by is_default desc, created_at asc
    limit 1;
  end if;

  if v_selected_account_id is null then
    return jsonb_build_object('success', false, 'error', 'payout_account_required');
  end if;

  select *
  into v_account
  from public.traveler_payout_accounts
  where id = v_selected_account_id
    and traveler_user_id = v_actor
  for update;

  if v_account.id is null then
    return jsonb_build_object('success', false, 'error', 'payout_account_invalid');
  end if;

  if coalesce(v_account.verification_status, 'pending') <> 'verified' then
    return jsonb_build_object('success', false, 'error', 'payout_account_verification_required');
  end if;

  perform 1
  from public.payouts p
  where p.traveler_user_id = v_actor
    and p.status in ('pending', 'approved')
  for update;

  select coalesce(sum(amount), 0)
  into v_reserved_amount
  from public.payouts p
  where p.traveler_user_id = v_actor
    and p.status in ('pending', 'approved');

  v_withdrawable := greatest(coalesce(v_wallet.available_balance, 0) - v_reserved_amount, 0);

  if p_amount > v_withdrawable then
    return jsonb_build_object(
      'success', false,
      'error', 'insufficient_withdrawable_balance',
      'withdrawable_balance', v_withdrawable
    );
  end if;

  insert into public.payouts (
    traveler_user_id,
    wallet_id,
    payout_account_id,
    amount,
    review_notes,
    payment_policy_version,
    payment_policy_accepted_at,
    payment_policy_acceptance_flow,
    legal_metadata
  ) values (
    v_actor,
    v_wallet.id,
    v_account.id,
    p_amount,
    nullif(btrim(coalesce(p_note, '')), ''),
    btrim(p_payment_policy_version),
    v_accepted_at,
    coalesce(nullif(btrim(p_payment_policy_acceptance_flow), ''), 'wallet_payout_request'),
    jsonb_build_object('payment_policy_accepted', true)
  )
  returning id into v_payout_id;

  insert into public.app_audit_logs (actor_id, event_type, entity_type, entity_id, metadata)
  values (
    v_actor,
    'payout_requested',
    'payout',
    v_payout_id,
    jsonb_build_object(
      'amount', p_amount,
      'wallet_id', v_wallet.id,
      'payout_account_id', v_account.id,
      'payment_policy_version', btrim(p_payment_policy_version)
    )
  );

  return jsonb_build_object('success', true, 'payout_id', v_payout_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_notification(p_notification_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'No autenticado');
  end if;
  delete from public.notifications
  where id = p_notification_id
    and user_id = v_actor;
  if not found then
    return jsonb_build_object('success', false, 'error', 'notification_not_found');
  end if;
  return jsonb_build_object('success', true, 'notification_id', p_notification_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.reject_match(p_match_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_trip_id uuid;
  v_shipment_id uuid;
  v_owner_id uuid;
  v_traveler_id uuid;
begin
  if v_actor is null then
    raise exception 'No autenticado';
  end if;

  select m.trip_id, m.shipment_id
  into v_trip_id, v_shipment_id
  from public.matches m
  where m.id = p_match_id
  for update;

  if v_trip_id is null then
    raise exception 'Match no existe';
  end if;

  select s.owner_id
  into v_owner_id
  from public.shipments s
  where s.id = v_shipment_id;

  if v_owner_id is null then
    raise exception 'Shipment no existe';
  end if;

  if v_actor <> v_owner_id then
    raise exception 'No autorizado (solo el cliente puede rechazar)';
  end if;

  update public.matches
  set status = 'rejected'
  where id = p_match_id
    and status = 'pending';

  if not found then
    raise exception 'Match no estaba en pending (ya fue procesado)';
  end if;

  select t.traveler_id
  into v_traveler_id
  from public.trips t
  where t.id = v_trip_id;

  perform public.create_operational_notification(
    v_traveler_id,
    'match_rejected',
    'Tu solicitud fue rechazada',
    'El cliente rechazo tu solicitud de transporte.',
    p_match_id,
    null,
    true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_resolve_dispute_for_traveler(p_payment_id uuid, p_match_id uuid DEFAULT NULL::uuid, p_resolution_notes text DEFAULT NULL::text, p_admin_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_payment public.payments;
  v_match public.matches;
  v_shipment public.shipments;
  v_trip public.trips;
  v_now timestamptz := now();
  v_notes text := nullif(btrim(coalesce(p_resolution_notes, '')), '');
  v_amount numeric := 0;
  v_report_id uuid;
begin
  if p_payment_id is null then
    return jsonb_build_object('success', false, 'error', 'payment_required');
  end if;

  if v_notes is null then
    return jsonb_build_object('success', false, 'error', 'resolution_notes_required');
  end if;

  select *
  into v_payment
  from public.payments
  where id = p_payment_id
  for update;

  if v_payment.id is null then
    return jsonb_build_object('success', false, 'error', 'payment_not_found');
  end if;

  if v_payment.status = 'released' then
    return jsonb_build_object('success', false, 'error', 'already_released');
  end if;

  if v_payment.status in ('refunded', 'cancelled', 'failed') then
    return jsonb_build_object('success', false, 'error', 'payment_already_closed');
  end if;

  if v_payment.status <> 'held' then
    return jsonb_build_object('success', false, 'error', 'payment_not_held');
  end if;

  if lower(coalesce(v_payment.gateway_status, '')) <> 'approved' then
    return jsonb_build_object('success', false, 'error', 'payment_not_approved');
  end if;

  if coalesce(v_payment.refund_status, 'none') <> 'none'
    or lower(coalesce(v_payment.metadata ->> 'manual_refund_required', 'false')) = 'true'
  then
    return jsonb_build_object('success', false, 'error', 'payment_blocked');
  end if;

  if coalesce(v_payment.dispute_status, 'none') <> 'open' then
    return jsonb_build_object('success', false, 'error', 'dispute_not_open');
  end if;

  select *
  into v_match
  from public.matches
  where id = coalesce(p_match_id, v_payment.match_id)
  for update;

  if v_match.id is null or v_match.id <> v_payment.match_id then
    return jsonb_build_object('success', false, 'error', 'match_not_found');
  end if;

  select *
  into v_shipment
  from public.shipments
  where id = v_match.shipment_id
  for update;

  select *
  into v_trip
  from public.trips
  where id = v_match.trip_id;

  if v_shipment.id is null or v_trip.id is null or v_trip.traveler_id is null then
    return jsonb_build_object('success', false, 'error', 'match_context_not_found');
  end if;

  v_amount := coalesce(v_payment.traveler_amount, v_payment.amount);

  if v_amount is null or v_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'invalid_release_amount');
  end if;

  if not exists (
    select 1
    from public.wallet_ledger
    where payment_id = v_payment.id
      and entry_type = 'release_pending_debit'
  ) then
    perform public.add_wallet_ledger_entry(
      v_trip.traveler_id,
      v_payment.id,
      v_match.id,
      null,
      'release_pending_debit',
      'pending',
      'debit',
      v_amount,
      'Liberacion de retencion temporal por resolucion admin',
      jsonb_build_object('reason', 'admin_dispute_resolution', 'admin_id', p_admin_id)
    );
  end if;

  if not exists (
    select 1
    from public.wallet_ledger
    where payment_id = v_payment.id
      and entry_type = 'release_available_credit'
  ) then
    perform public.add_wallet_ledger_entry(
      v_trip.traveler_id,
      v_payment.id,
      v_match.id,
      null,
      'release_available_credit',
      'available',
      'credit',
      v_amount,
      'Saldo disponible por disputa resuelta a favor del viajero',
      jsonb_build_object('reason', 'admin_dispute_resolution', 'admin_id', p_admin_id)
    );
  end if;

  update public.payments
  set
    status = 'released',
    released_at = v_now,
    released_by = 'admin_dispute_resolution',
    dispute_status = 'resolved',
    dispute_resolved_at = v_now,
    updated_at = v_now,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'admin_dispute_status', 'resolved',
      'admin_dispute_resolution', 'traveler_release',
      'admin_dispute_resolved_by', p_admin_id,
      'admin_dispute_resolved_at', v_now,
      'admin_dispute_notes', v_notes
    )
  where id = v_payment.id;

  update public.matches
  set
    status = 'resolved',
    resolved_at = v_now,
    resolution_notes = v_notes
  where id = v_match.id;

  if v_shipment.status = 'in_transit' and v_payment.traveler_delivered_at is not null then
    update public.shipments
    set status = 'delivered'
    where id = v_shipment.id;
  end if;

  if coalesce(v_payment.metadata, '{}'::jsonb) ? 'escalated_from_report_id' then
    begin
      v_report_id := nullif(v_payment.metadata ->> 'escalated_from_report_id', '')::uuid;
    exception when invalid_text_representation then
      v_report_id := null;
    end;
  end if;

  if v_report_id is not null then
    update public.shipment_report_events
    set
      status = 'resolved',
      resolved_at = coalesce(resolved_at, v_now),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'dispute_resolution', 'traveler_release',
        'dispute_resolved_at', v_now,
        'dispute_resolved_by', p_admin_id,
        'dispute_resolution_notes', v_notes
      )
    where id = v_report_id;
  end if;

  insert into public.app_audit_logs (actor_id, event_type, entity_type, entity_id, metadata)
  values (
    p_admin_id,
    'dispute_resolved_traveler_release',
    'payment',
    v_payment.id,
    jsonb_build_object(
      'match_id', v_match.id,
      'shipment_id', v_shipment.id,
      'traveler_user_id', v_trip.traveler_id,
      'amount', v_amount,
      'report_id', v_report_id,
      'resolution_notes', v_notes
    )
  );

  perform public.sync_wallet_balance(v_trip.traveler_id);

  return jsonb_build_object(
    'success', true,
    'payment_id', v_payment.id,
    'match_id', v_match.id,
    'status', 'released'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_user_verification_operational_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_type text;
begin
  if coalesce(old.verification_status, '') = coalesce(new.verification_status, '')
    or new.verification_status not in ('verified', 'rejected')
  then
    return new;
  end if;

  v_type := case
    when new.verification_status = 'verified' then 'verification_approved'
    else 'verification_rejected'
  end;

  perform public.create_operational_notification(
    new.user_id,
    v_type,
    case when new.verification_status = 'verified' then 'Verificacion aprobada' else 'Verificacion rechazada' end,
    case when new.verification_status = 'verified' then 'Tu verificacion fue aprobada.' else 'Tu verificacion fue rechazada.' end,
    null,
    'verification:' || new.id::text || ':' || new.verification_status,
    true
  );

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.refund_payment(p_payment_id uuid, p_reason text DEFAULT 'cancelled'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_payment public.payments;
  v_traveler_user_id uuid;
  v_owner_id uuid;
  v_amount numeric := 0;
begin
  select *
  into v_payment
  from public.payments
  where id = p_payment_id
  for update;

  if v_payment.id is null then
    return jsonb_build_object('success', false, 'error', 'payment_not_found');
  end if;

  select t.traveler_id, s.owner_id
  into v_traveler_user_id, v_owner_id
  from public.matches m
  join public.trips t on t.id = m.trip_id
  join public.shipments s on s.id = m.shipment_id
  where m.id = v_payment.match_id;

  if v_actor is not null and v_actor <> v_owner_id and v_actor <> v_traveler_user_id then
    raise exception 'No autorizado';
  end if;

  if v_payment.status = 'refunded' or coalesce(v_payment.refund_status, 'none') = 'refunded' then
    return jsonb_build_object('success', false, 'error', 'already_processed');
  end if;

  v_amount := coalesce(v_payment.traveler_amount, v_payment.amount);

  if v_traveler_user_id is not null then
    if exists (
      select 1 from public.wallet_ledger
      where payment_id = v_payment.id
        and entry_type = 'payment_hold'
    ) and not exists (
      select 1 from public.wallet_ledger
      where payment_id = v_payment.id
        and entry_type = 'refund_pending_debit'
    ) then
      perform public.add_wallet_ledger_entry(
        v_traveler_user_id,
        v_payment.id,
        v_payment.match_id,
        null,
        'refund_pending_debit',
        'pending',
        'debit',
        v_amount,
        'Reverso de retencion temporal por reembolso',
        jsonb_build_object('reason', p_reason)
      );
    end if;

    if exists (
      select 1 from public.wallet_ledger
      where payment_id = v_payment.id
        and entry_type = 'release_available_credit'
    ) and not exists (
      select 1 from public.wallet_ledger
      where payment_id = v_payment.id
        and entry_type = 'refund_available_debit'
    ) then
      perform public.add_wallet_ledger_entry(
        v_traveler_user_id,
        v_payment.id,
        v_payment.match_id,
        null,
        'refund_available_debit',
        'available',
        'debit',
        v_amount,
        'Ajuste por reembolso del cliente',
        jsonb_build_object('reason', p_reason)
      );
    end if;

    perform public.sync_wallet_balance(v_traveler_user_id);
  end if;

  update public.payments
  set
    status = 'refunded',
    refund_status = 'refunded',
    refund_reason = coalesce(refund_reason, p_reason),
    refund_processed_at = coalesce(refund_processed_at, now()),
    refunded_at = coalesce(refunded_at, now()),
    dispute_status = case when dispute_status = 'open' then 'resolved' else dispute_status end,
    updated_at = now(),
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('refund_reason', p_reason)
  where id = v_payment.id;

  return jsonb_build_object('success', true, 'payment_id', v_payment.id);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_payment_retry(p_shipment_id uuid, p_retry_payment_id uuid DEFAULT NULL::uuid, p_payment_policy_accepted boolean DEFAULT false, p_payment_policy_version text DEFAULT '1.0'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_shipment public.shipments%rowtype;
  v_latest_payment public.payments%rowtype;
  v_base_amount integer;
  v_customer_amount integer;
  v_quote jsonb;
  v_payment_id uuid;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'not_authenticated');
  end if;

  if p_shipment_id is null or not coalesce(p_payment_policy_accepted, false)
    or nullif(btrim(coalesce(p_payment_policy_version, '')), '') is null then
    return jsonb_build_object('success', false, 'error', 'invalid_request');
  end if;

  -- Serialize retries for a shipment so two checkout clicks cannot create two attempts.
  select * into v_shipment
  from public.shipments s
  where s.id = p_shipment_id and s.owner_id = v_actor
  for update;

  if v_shipment.id is null or v_shipment.status <> 'open' then
    return jsonb_build_object('success', false, 'error', 'shipment_not_payable');
  end if;

  if not exists (
    select 1 from public.shipment_evidence e
    where e.shipment_id = p_shipment_id
      and e.evidence_type = 'customer_initial_photo'
      and e.uploaded_by = v_actor
  ) then
    return jsonb_build_object('success', false, 'error', 'initial_evidence_required');
  end if;

  -- Serialize against webhook/admin updates to existing payment attempts.
  perform 1 from public.payments p
  where p.shipment_id = p_shipment_id
  order by p.created_at, p.id
  for update;

  -- A charge already approved or held must never be followed by another charge.
  if exists (
    select 1 from public.payments p
    where p.shipment_id = p_shipment_id
      and (p.status in ('held', 'released', 'refunded')
        or lower(coalesce(p.gateway_status, '')) = 'approved')
  ) then
    return jsonb_build_object('success', false, 'error', 'payment_already_approved');
  end if;

  select * into v_latest_payment
  from public.payments p
  where p.shipment_id = p_shipment_id
  order by p.created_at desc, p.id desc
  limit 1;

  if v_latest_payment.id is not null then
    if v_latest_payment.user_id is distinct from v_actor then
      return jsonb_build_object('success', false, 'error', 'payment_not_retryable');
    end if;

    if v_latest_payment.status in ('pending', 'processing') then
      return jsonb_build_object(
        'success', true, 'shipment_id', p_shipment_id,
        'payment_id', v_latest_payment.id, 'reused', true
      );
    end if;

    if v_latest_payment.status not in ('failed', 'cancelled')
      or (p_retry_payment_id is not null
        and p_retry_payment_id <> v_latest_payment.id) then
      return jsonb_build_object('success', false, 'error', 'payment_not_retryable');
    end if;

    if exists (
      select 1 from public.payments p
      where p.shipment_id = p_shipment_id
        and p.id <> v_latest_payment.id
        and p.status in ('pending', 'processing')
    ) then
      return jsonb_build_object('success', false, 'error', 'pending_payment_exists');
    end if;
  elsif p_retry_payment_id is not null then
    return jsonb_build_object('success', false, 'error', 'payment_not_retryable');
  end if;

  select rp.base_price, rp.customer_price
  into v_base_amount, v_customer_amount
  from public.route_prices rp
  where rp.origin_city_id = v_shipment.origin_city_id
    and rp.destination_city_id = v_shipment.destination_city_id
    and rp.is_active = true
  order by rp.updated_at desc, rp.created_at desc
  limit 1;

  if v_base_amount is null or v_customer_amount is null then
    return jsonb_build_object('success', false, 'error', 'route_not_available');
  end if;

  v_quote := public.calculate_payment_amount(v_base_amount, v_customer_amount);
  if not coalesce((v_quote ->> 'success')::boolean, false) then
    return jsonb_build_object('success', false, 'error', 'quote_error');
  end if;

  insert into public.payments (
    shipment_id, user_id, amount, gross_amount, traveler_amount, intra_fee,
    gateway_fee_estimated, net_amount_received, currency, status,
    gateway_provider, gateway_status, payment_method, external_reference, metadata
  ) values (
    p_shipment_id, v_actor,
    (v_quote ->> 'amount')::numeric,
    (v_quote ->> 'gross_amount')::numeric,
    (v_quote ->> 'traveler_amount')::numeric,
    (v_quote ->> 'intra_fee')::numeric,
    (v_quote ->> 'gateway_fee_estimated')::numeric,
    (v_quote ->> 'net_amount_received')::numeric,
    coalesce(v_quote ->> 'currency', 'COP'),
    'pending', 'wompi', 'created', 'wompi_widget',
    'intra-shipment-' || p_shipment_id::text || '-' || gen_random_uuid()::text,
    jsonb_build_object(
      'source', 'payment_retry_rpc',
      'auto_release_hours', coalesce((v_quote ->> 'auto_release_hours')::integer, 48),
      'dispute_window_hours', coalesce((v_quote ->> 'dispute_window_hours')::integer, 24),
      'payment_conditions_accepted', true,
      'payment_conditions_version', btrim(p_payment_policy_version),
      'payment_conditions_flow', 'shipment_checkout',
      'retry_of_payment_id', v_latest_payment.id
    )
  ) returning id into v_payment_id;

  return jsonb_build_object(
    'success', true, 'shipment_id', p_shipment_id,
    'payment_id', v_payment_id, 'reused', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.generate_payout_code()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  candidate text;
begin
  loop
    candidate := 'INTRA-WDR-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));

    exit when not exists (
      select 1
      from public.payouts p
      where p.payout_code = candidate
    );
  end loop;

  return candidate;
end;
$function$

CREATE OR REPLACE FUNCTION public.release_payment(p_payment_id uuid, p_reason text DEFAULT 'delivery_completed'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_payment public.payments;
  v_traveler_user_id uuid;
  v_owner_id uuid;
  v_amount numeric := 0;
begin
  select *
  into v_payment
  from public.payments
  where id = p_payment_id
  for update;

  if v_payment.id is null then
    return jsonb_build_object('success', false, 'error', 'payment_not_found');
  end if;

  select t.traveler_id, s.owner_id
  into v_traveler_user_id, v_owner_id
  from public.matches m
  join public.trips t on t.id = m.trip_id
  join public.shipments s on s.id = m.shipment_id
  where m.id = v_payment.match_id;

  if v_actor is not null and v_actor <> v_owner_id then
    raise exception 'No autorizado';
  end if;

  if v_payment.status <> 'held' then
    return jsonb_build_object('success', false, 'error', 'payment_not_held');
  end if;

  if lower(coalesce(v_payment.gateway_status, '')) <> 'approved' then
    return jsonb_build_object('success', false, 'error', 'payment_not_approved');
  end if;

  if v_payment.dispute_status = 'open' then
    return jsonb_build_object('success', false, 'error', 'match_in_dispute');
  end if;

  if coalesce(v_payment.refund_status, 'none') <> 'none'
    or lower(coalesce(v_payment.metadata ->> 'manual_refund_required', 'false')) = 'true'
  then
    return jsonb_build_object('success', false, 'error', 'payment_blocked');
  end if;

  if v_traveler_user_id is null then
    return jsonb_build_object('success', false, 'error', 'wallet_not_found');
  end if;

  v_amount := coalesce(v_payment.traveler_amount, v_payment.amount);

  if not exists (
    select 1 from public.wallet_ledger
    where payment_id = v_payment.id
      and entry_type = 'release_pending_debit'
  ) then
    perform public.add_wallet_ledger_entry(
      v_traveler_user_id,
      v_payment.id,
      v_payment.match_id,
      null,
      'release_pending_debit',
      'pending',
      'debit',
      v_amount,
      'Liberacion de retencion temporal',
      jsonb_build_object('reason', p_reason)
    );
  end if;

  if not exists (
    select 1 from public.wallet_ledger
    where payment_id = v_payment.id
      and entry_type = 'release_available_credit'
  ) then
    perform public.add_wallet_ledger_entry(
      v_traveler_user_id,
      v_payment.id,
      v_payment.match_id,
      null,
      'release_available_credit',
      'available',
      'credit',
      v_amount,
      'Saldo disponible por entrega completada',
      jsonb_build_object('reason', p_reason)
    );
  end if;

  update public.payments
  set
    status = 'released',
    released_at = now(),
    released_by = p_reason,
    dispute_status = case when dispute_status = 'open' then 'resolved' else dispute_status end,
    updated_at = now()
  where id = v_payment.id;

  perform public.sync_wallet_balance(v_traveler_user_id);

  return jsonb_build_object('success', true, 'payment_id', v_payment.id);
end;
$function$

CREATE OR REPLACE FUNCTION public.process_wompi_payment_event(p_gateway_transaction_id text, p_status text, p_external_reference text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_payment public.payments;
  v_normalized_status text;
  v_previous_status text;
  v_new_status text;
begin
  v_normalized_status := lower(coalesce(p_status, ''));

  select *
  into v_payment
  from public.payments
  where (
    (p_gateway_transaction_id is not null and gateway_transaction_id = p_gateway_transaction_id)
    or (p_external_reference is not null and external_reference = p_external_reference)
  )
  order by created_at desc
  limit 1
  for update;

  if v_payment.id is null then
    return jsonb_build_object('success', false, 'error', 'payment_not_found');
  end if;

  v_previous_status := v_payment.status;
  v_new_status := v_payment.status;

  if v_normalized_status = 'approved'
    and v_payment.status in ('pending', 'processing')
    and coalesce(v_payment.refund_status, 'none') = 'none'
    and lower(coalesce(v_payment.metadata ->> 'manual_refund_required', 'false')) <> 'true'
  then
    v_new_status := 'held';
  elsif v_normalized_status in ('failed', 'rejected', 'declined', 'error')
    and v_payment.status in ('pending', 'processing')
  then
    v_new_status := 'failed';
  elsif v_normalized_status in ('cancelled', 'canceled', 'voided')
    and v_payment.status in ('pending', 'processing')
  then
    v_new_status := 'cancelled';
  end if;

  update public.payments
  set
    gateway_transaction_id = coalesce(p_gateway_transaction_id, gateway_transaction_id),
    gateway_status = p_status,
    status = v_new_status,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('last_wompi_event', coalesce(p_payload, '{}'::jsonb)),
    updated_at = now()
  where id = v_payment.id;

  return jsonb_build_object(
    'success', true,
    'payment_id', v_payment.id,
    'previous_status', v_previous_status,
    'status', v_new_status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_match(p_match_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_requester_id uuid;
  v_owner_id uuid;
  v_traveler_id uuid;
  v_shipment_id uuid;
  v_trip_id uuid;
  v_match_status text;
  v_shipment_status text;
  v_recipient_id uuid;
  v_payment public.payments;
  v_payment_id uuid;
  v_payment_status text;
  v_amount numeric := 0;
  v_reason text := coalesce(nullif(trim(coalesce(p_reason, '')), ''), 'match_cancelled');
begin
  if v_actor is null then
    return json_build_object(
      'success', false,
      'error', 'No autenticado'
    );
  end if;

  select
    m.requester_id,
    s.owner_id,
    t.traveler_id,
    m.shipment_id,
    m.trip_id,
    m.status,
    s.status
  into
    v_requester_id,
    v_owner_id,
    v_traveler_id,
    v_shipment_id,
    v_trip_id,
    v_match_status,
    v_shipment_status
  from public.matches m
  join public.shipments s on s.id = m.shipment_id
  join public.trips t on t.id = m.trip_id
  where m.id = p_match_id
  for update;

  if v_requester_id is null then
    return json_build_object(
      'success', false,
      'error', 'Match no encontrado'
    );
  end if;

  if v_actor not in (v_requester_id, v_owner_id, v_traveler_id) then
    return json_build_object(
      'success', false,
      'error', 'No autorizado'
    );
  end if;

  if v_match_status not in ('pending', 'accepted') then
    return json_build_object(
      'success', false,
      'error', 'No se pudo cancelar el match'
    );
  end if;

  if v_match_status = 'accepted' then
    if v_shipment_status not in ('open', 'matched') then
      return json_build_object(
        'success', false,
        'error', 'El envio ya fue recibido por el viajero. Abre una disputa para revisarlo.'
      );
    end if;

    select *
    into v_payment
    from public.payments p
    where p.shipment_id = v_shipment_id
    order by p.created_at desc
    limit 1
    for update;

    v_payment_id := v_payment.id;
    v_payment_status := v_payment.status;

    if v_payment_id is null then
      return json_build_object(
        'success', false,
        'error', 'No se encontro un pago asociado a este envio'
      );
    end if;

    if v_payment.status = 'released' then
      return json_build_object('success', false, 'error', 'El pago ya fue liberado');
    end if;

    if v_payment.status not in ('refunded', 'failed', 'cancelled') then
      v_amount := coalesce(v_payment.traveler_amount, v_payment.gross_amount, v_payment.amount);

      if exists (
        select 1
        from public.wallet_ledger wl
        where wl.payment_id = v_payment.id
          and wl.entry_type = 'payment_hold'
      ) and not exists (
        select 1
        from public.wallet_ledger wl
        where wl.payment_id = v_payment.id
          and wl.entry_type = 'refund_pending_debit'
      ) then
        perform public.add_wallet_ledger_entry(
          v_traveler_id,
          v_payment.id,
          p_match_id,
          null,
          'refund_pending_debit',
          'pending',
          'debit',
          v_amount,
          'Reverso de retencion por cancelacion antes de recogida',
          jsonb_build_object('source', 'cancel_match', 'reason', v_reason)
        );

        perform public.sync_wallet_balance(v_traveler_id);
      end if;

      update public.payments
      set
        refund_status = 'manual_required',
        refund_reason = v_reason,
        refund_requested_at = coalesce(refund_requested_at, now()),
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'manual_refund_required', true,
          'manual_refund_reason', v_reason,
          'cancelled_match_id', p_match_id,
          'cancelled_at', now()
        ),
        updated_at = now()
      where id = v_payment_id;
    end if;

    update public.shipments
    set status = 'cancelled'
    where id = v_shipment_id
      and status in ('open', 'matched');

    update public.trips
    set status = 'open'
    where id = v_trip_id
      and status not in ('closed', 'completed', 'cancelled');
  end if;

  update public.matches
  set status = 'cancelled'
  where id = p_match_id;

  v_recipient_id := case
    when v_actor = v_owner_id then v_traveler_id
    else v_owner_id
  end;

  if v_recipient_id is not null and v_recipient_id <> v_actor then
    insert into public.notifications (
      user_id,
      type,
      title,
      message,
      related_match_id
    )
    select
      v_recipient_id,
      'match_cancelled',
      'El match fue cancelado',
      'La otra parte cancelo este match.',
      p_match_id
    where not exists (
      select 1
      from public.notifications n
      where n.user_id = v_recipient_id
        and n.type = 'match_cancelled'
        and n.related_match_id = p_match_id
    );
  end if;

  return json_build_object(
    'success', true,
    'manual_refund_required', v_match_status = 'accepted' and v_payment_status not in ('refunded', 'failed', 'cancelled')
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_review(p_match_id uuid, p_rating smallint, p_comment text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_owner_id uuid;
  v_traveler_id uuid;
  v_shipment_id uuid;
  v_match_status text;
  v_reviewed_user_id uuid;
  v_review_id uuid;
  v_comment text := nullif(btrim(coalesce(p_comment, '')), '');
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'No autenticado');
  end if;

  if p_rating is null or p_rating < 1 or p_rating > 5 then
    return jsonb_build_object('success', false, 'error', 'El rating debe estar entre 1 y 5');
  end if;

  if v_comment is not null and char_length(v_comment) > 300 then
    return jsonb_build_object('success', false, 'error', 'El comentario no puede superar 300 caracteres');
  end if;

  select
    s.owner_id,
    t.traveler_id,
    m.shipment_id,
    m.status
  into
    v_owner_id,
    v_traveler_id,
    v_shipment_id,
    v_match_status
  from public.matches m
  join public.shipments s on s.id = m.shipment_id
  join public.trips t on t.id = m.trip_id
  where m.id = p_match_id;

  if v_shipment_id is null then
    return jsonb_build_object('success', false, 'error', 'Match no encontrado');
  end if;

  if v_match_status <> 'completed' then
    return jsonb_build_object('success', false, 'error', 'Solo puedes dejar una review cuando el match esté completado');
  end if;

  if v_actor = v_owner_id then
    v_reviewed_user_id := v_traveler_id;
  elsif v_actor = v_traveler_id then
    v_reviewed_user_id := v_owner_id;
  else
    return jsonb_build_object('success', false, 'error', 'No autorizado');
  end if;

  if v_reviewed_user_id is null or v_reviewed_user_id = v_actor then
    return jsonb_build_object('success', false, 'error', 'No puedes dejarte una review a ti mismo');
  end if;

  if exists (
    select 1
    from public.reviews r
    where r.match_id = p_match_id
      and r.reviewer_id = v_actor
  ) then
    return jsonb_build_object('success', false, 'error', 'Ya dejaste una review para este match');
  end if;

  insert into public.reviews (
    match_id,
    reviewer_id,
    reviewed_user_id,
    shipment_id,
    rating,
    comment
  )
  values (
    p_match_id,
    v_actor,
    v_reviewed_user_id,
    v_shipment_id,
    p_rating,
    v_comment
  )
  returning id into v_review_id;

  return jsonb_build_object(
    'success', true,
    'review_id', v_review_id,
    'reviewed_user_id', v_reviewed_user_id,
    'rating', p_rating
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.attach_payment_hold_to_match(p_match_id uuid, p_shipment_id uuid, p_traveler_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_payment public.payments;
  v_amount numeric := 0;
begin
  select *
  into v_payment
  from public.payments
  where shipment_id = p_shipment_id
    and status = 'held'
    and lower(coalesce(gateway_status, '')) = 'approved'
    and coalesce(refund_status, 'none') = 'none'
    and dispute_status = 'none'
    and lower(coalesce(metadata ->> 'manual_refund_required', 'false')) <> 'true'
  order by created_at desc
  limit 1
  for update;

  if v_payment.id is null then
    return jsonb_build_object(
      'success', false,
      'error', 'payment_not_approved'
    );
  end if;

  v_amount := coalesce(v_payment.traveler_amount, v_payment.gross_amount, v_payment.amount);

  update public.payments
  set
    match_id = p_match_id,
    traveler_amount = coalesce(traveler_amount, v_amount),
    gross_amount = coalesce(gross_amount, amount),
    net_amount_received = coalesce(net_amount_received, greatest(coalesce(gross_amount, amount) - coalesce(gateway_fee_actual, gateway_fee_estimated, 0), 0)),
    updated_at = now()
  where id = v_payment.id;

  perform public.ensure_wallet(p_traveler_user_id);

  if not exists (
    select 1
    from public.wallet_ledger wl
    where wl.payment_id = v_payment.id
      and wl.entry_type = 'payment_hold'
  ) then
    perform public.add_wallet_ledger_entry(
      p_traveler_user_id,
      v_payment.id,
      p_match_id,
      null,
      'payment_hold',
      'pending',
      'credit',
      v_amount,
      'Retencion temporal del pago asociada al match',
      jsonb_build_object('source', 'accept_match')
    );
  end if;

  return jsonb_build_object(
    'success', true,
    'payment_id', v_payment.id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.calculate_payment_amount(p_base_amount numeric, p_customer_amount numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_config public.fee_configs;
  v_gateway_percent_factor numeric := 0;
  v_intra_fee numeric := 0;
  v_total numeric := 0;
  v_gateway_fee numeric := 0;
  v_net numeric := 0;
begin
  select *
  into v_config
  from public.fee_configs
  where is_active = true
  order by updated_at desc, created_at desc
  limit 1;

  if v_config.id is null then
    return jsonb_build_object(
      'success', false,
      'error', 'fee_config_not_found'
    );
  end if;

  if p_base_amount is null or p_base_amount <= 0 then
    return jsonb_build_object(
      'success', false,
      'error', 'below_minimum',
      'minimum_amount', v_config.min_shipment_amount_cop
    );
  end if;

  if p_customer_amount is not null then
    if p_customer_amount < v_config.min_shipment_amount_cop then
      return jsonb_build_object(
        'success', false,
        'error', 'below_minimum',
        'minimum_amount', v_config.min_shipment_amount_cop
      );
    end if;

    v_gateway_fee := ceil(
      (p_customer_amount * coalesce(v_config.gateway_fee_percent, 0) / 100)
      + coalesce(v_config.gateway_fee_fixed_cop, 0)
    );
    v_intra_fee := p_customer_amount - p_base_amount - v_gateway_fee;
    v_total := p_customer_amount;
    v_net := greatest(v_total - v_gateway_fee, 0);

    if v_intra_fee < 0 then
      return jsonb_build_object(
        'success', false,
        'error', 'invalid_route_margin',
        'gateway_fee_estimated', v_gateway_fee,
        'minimum_amount', v_config.min_shipment_amount_cop
      );
    end if;

    return jsonb_build_object(
      'success', true,
      'traveler_amount', p_base_amount,
      'gross_amount', v_total,
      'amount', v_total,
      'gateway_fee_estimated', v_gateway_fee,
      'intra_fee', v_intra_fee,
      'net_amount_received', v_net,
      'minimum_amount', v_config.min_shipment_amount_cop,
      'minimum_payout', v_config.minimum_payout_cop,
      'dispute_window_hours', v_config.dispute_window_hours,
      'dispute_sla_hours', v_config.dispute_sla_hours,
      'auto_release_hours', v_config.auto_release_hours,
      'currency', 'COP'
    );
  end if;

  if p_base_amount < v_config.min_shipment_amount_cop then
    return jsonb_build_object(
      'success', false,
      'error', 'below_minimum',
      'minimum_amount', v_config.min_shipment_amount_cop
    );
  end if;

  v_intra_fee := ceil((p_base_amount * v_config.customer_fee_percent / 100) + v_config.customer_fee_fixed_cop);
  v_gateway_percent_factor := coalesce(v_config.gateway_fee_percent, 0) / 100;

  if v_gateway_percent_factor >= 1 then
    return jsonb_build_object(
      'success', false,
      'error', 'invalid_gateway_fee_config'
    );
  end if;

  v_total := ceil(
    (p_base_amount + v_intra_fee + coalesce(v_config.gateway_fee_fixed_cop, 0))
    / (1 - v_gateway_percent_factor)
  );

  v_gateway_fee := greatest(v_total - p_base_amount - v_intra_fee, 0);
  v_net := greatest(v_total - v_gateway_fee, 0);

  return jsonb_build_object(
    'success', true,
    'traveler_amount', p_base_amount,
    'gross_amount', v_total,
    'amount', v_total,
    'gateway_fee_estimated', v_gateway_fee,
    'intra_fee', v_intra_fee,
    'net_amount_received', v_net,
    'minimum_amount', v_config.min_shipment_amount_cop,
    'minimum_payout', v_config.minimum_payout_cop,
    'dispute_window_hours', v_config.dispute_window_hours,
    'dispute_sla_hours', v_config.dispute_sla_hours,
    'auto_release_hours', v_config.auto_release_hours,
    'currency', 'COP'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_payout_status(p_payout_id uuid, p_status text, p_review_notes text DEFAULT NULL::text, p_paid_reference text DEFAULT NULL::text, p_admin_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_payout public.payouts;
  v_wallet public.wallets;
  v_now timestamptz := now();
  v_ledger_id uuid;
  v_review_notes text := nullif(btrim(coalesce(p_review_notes, '')), '');
  v_paid_reference text := nullif(btrim(coalesce(p_paid_reference, '')), '');
begin
  if p_payout_id is null then
    return jsonb_build_object('success', false, 'error', 'payout_required');
  end if;

  if p_status not in ('approved', 'rejected', 'paid') then
    return jsonb_build_object('success', false, 'error', 'invalid_payout_status');
  end if;

  select *
  into v_payout
  from public.payouts
  where id = p_payout_id
  for update;

  if v_payout.id is null then
    return jsonb_build_object('success', false, 'error', 'payout_not_found');
  end if;

  if v_payout.status = 'paid' then
    if p_status = 'paid' then
      return jsonb_build_object('success', true, 'payout_id', v_payout.id, 'status', 'paid', 'idempotent', true);
    end if;

    return jsonb_build_object('success', false, 'error', 'invalid_payout_transition');
  end if;

  if p_status = 'approved' and v_payout.status <> 'pending' then
    return jsonb_build_object('success', false, 'error', 'invalid_payout_transition');
  end if;

  if p_status = 'rejected' and v_payout.status not in ('pending', 'approved') then
    return jsonb_build_object('success', false, 'error', 'invalid_payout_transition');
  end if;

  if p_status = 'paid' and v_payout.status <> 'approved' then
    return jsonb_build_object('success', false, 'error', 'payout_must_be_approved_first');
  end if;

  if p_status = 'paid' and v_paid_reference is null then
    return jsonb_build_object('success', false, 'error', 'paid_reference_required');
  end if;

  if p_status = 'paid' then
    select *
    into v_wallet
    from public.wallets
    where id = v_payout.wallet_id
    for update;

    if v_wallet.id is null then
      return jsonb_build_object('success', false, 'error', 'wallet_not_found');
    end if;

    if coalesce(v_wallet.available_balance, 0) < v_payout.amount then
      return jsonb_build_object('success', false, 'error', 'insufficient_wallet_balance');
    end if;

    insert into public.wallet_ledger (
      wallet_id,
      user_id,
      payout_id,
      entry_type,
      balance_type,
      direction,
      amount,
      description,
      metadata
    ) values (
      v_payout.wallet_id,
      v_payout.traveler_user_id,
      v_payout.id,
      'payout_paid_debit',
      'available',
      'debit',
      v_payout.amount,
      'Retiro pagado al usuario',
      jsonb_build_object(
        'source', 'admin_payout_review',
        'paid_reference', v_paid_reference,
        'admin_id', p_admin_id
      )
    )
    on conflict do nothing
    returning id into v_ledger_id;

    if v_ledger_id is null then
      return jsonb_build_object('success', false, 'error', 'payout_already_has_paid_ledger');
    end if;

    update public.wallets
    set
      available_balance = coalesce(available_balance, 0) - v_payout.amount,
      total_withdrawn = coalesce(total_withdrawn, 0) + v_payout.amount,
      updated_at = v_now
    where id = v_wallet.id;
  end if;

  update public.payouts
  set
    status = p_status,
    reviewed_at = case when p_status in ('approved', 'rejected', 'paid') then v_now else reviewed_at end,
    paid_at = case when p_status = 'paid' then v_now else paid_at end,
    paid_reference = case when p_status = 'paid' then v_paid_reference else paid_reference end,
    review_notes = v_review_notes,
    updated_at = v_now
  where id = v_payout.id;

  insert into public.app_audit_logs (actor_id, event_type, entity_type, entity_id, metadata)
  values (
    p_admin_id,
    'payout_status_updated',
    'payout',
    v_payout.id,
    jsonb_build_object(
      'previous_status', v_payout.status,
      'new_status', p_status,
      'amount', v_payout.amount,
      'paid_reference', v_paid_reference
    )
  );

  return jsonb_build_object('success', true, 'payout_id', v_payout.id, 'status', p_status);
end;
$function$

CREATE OR REPLACE FUNCTION public.clear_user_notifications(p_only_read boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_deleted_count integer := 0;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'No autenticado');
  end if;
  delete from public.notifications
  where user_id = v_actor
    and (not coalesce(p_only_read, false) or is_read = true);
  get diagnostics v_deleted_count = row_count;
  return jsonb_build_object(
    'success', true,
    'deleted_count', v_deleted_count,
    'only_read', coalesce(p_only_read, false)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_shipment_with_payment_draft(p_origin_city_id uuid, p_destination_city_id uuid, p_kind text, p_description text, p_weight_kg numeric, p_declared_value_cop numeric, p_declaration_accepted boolean, p_declaration_version text DEFAULT '1.0'::text, p_is_fragile boolean DEFAULT false, p_is_urgent boolean DEFAULT false, p_is_high_value boolean DEFAULT false, p_acceptance_flow text DEFAULT 'shipment_checkout'::text, p_user_agent text DEFAULT NULL::text, p_ip_address inet DEFAULT NULL::inet, p_shipping_policy_version text DEFAULT '1.0'::text, p_payment_policy_accepted boolean DEFAULT false, p_payment_policy_version text DEFAULT '1.0'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_verification_status text := 'unverified';
  v_is_verified_v1 boolean := false;
  v_active_shipments integer := 0;
  v_shipments_last_7_days integer := 0;
  v_base_amount integer;
  v_customer_amount integer;
  v_quote jsonb;
  v_shipment_id uuid;
  v_payment_id uuid;
  v_tracking_code text;
  v_external_reference text;
  v_attempts integer := 0;
  v_declared_value_limit integer := 300000;
  v_accepted_at timestamptz := now();
  v_ip_address inet := public.get_request_ip();
  v_declaration_text text := 'Declaro que el contenido de este envío es lícito, corresponde a la información registrada y no contiene artículos prohibidos por la ley colombiana (armas, drogas, explosivos, dinero en efectivo, mercancía ilegal o falsificada, materiales peligrosos). Entiendo que mi identidad verificada queda asociada a este envío y que cualquier falsedad será mi responsabilidad exclusiva.';
begin
  if v_actor is null then
    return jsonb_build_object(
      'success', false,
      'error', 'not_authenticated'
    );
  end if;

  if p_origin_city_id is null or p_destination_city_id is null then
    return jsonb_build_object(
      'success', false,
      'error', 'route_required'
    );
  end if;

  if p_origin_city_id = p_destination_city_id then
    return jsonb_build_object(
      'success', false,
      'error', 'same_route'
    );
  end if;

  if p_kind is null or p_kind not in ('document', 'package', 'ecommerce') then
    return jsonb_build_object(
      'success', false,
      'error', 'kind_not_allowed'
    );
  end if;

  if coalesce(length(btrim(p_description)), 0) < 8 then
    return jsonb_build_object(
      'success', false,
      'error', 'invalid_description'
    );
  end if;

  if p_weight_kg is null or p_weight_kg < 0.1 or p_weight_kg > 10 then
    return jsonb_build_object(
      'success', false,
      'error', case when p_weight_kg > 10 then 'weight_limit_exceeded' else 'invalid_weight' end,
      'weight_limit_kg', 10
    );
  end if;

  if p_declared_value_cop is null or p_declared_value_cop < 0 then
    return jsonb_build_object(
      'success', false,
      'error', 'invalid_declared_value'
    );
  end if;

  if coalesce(p_declaration_accepted, false) = false then
    return jsonb_build_object(
      'success', false,
      'error', 'declaration_required'
    );
  end if;

  if coalesce(p_payment_policy_accepted, false) = false then
    return jsonb_build_object(
      'success', false,
      'error', 'payment_policy_required'
    );
  end if;

  if nullif(btrim(coalesce(p_shipping_policy_version, '')), '') is null then
    return jsonb_build_object(
      'success', false,
      'error', 'invalid_shipping_policy_version'
    );
  end if;

  if nullif(btrim(coalesce(p_payment_policy_version, '')), '') is null then
    return jsonb_build_object(
      'success', false,
      'error', 'invalid_payment_policy_version'
    );
  end if;

  select coalesce(uv.verification_status, 'unverified')
  into v_verification_status
  from public.user_verifications uv
  where uv.user_id = v_actor
  limit 1;

  v_is_verified_v1 := public.is_user_verified_v1(v_actor);

  if v_is_verified_v1 then
    v_declared_value_limit := 2000000;
  end if;

  if p_declared_value_cop > v_declared_value_limit then
    return jsonb_build_object(
      'success', false,
      'error', 'declared_value_limit_exceeded',
      'declared_value_limit_cop', v_declared_value_limit,
      'verification_status', v_verification_status,
      'verified_v1', v_is_verified_v1
    );
  end if;

  if not v_is_verified_v1 then
    select count(*)
    into v_active_shipments
    from public.shipments s
    where s.owner_id = v_actor
      and coalesce(s.status, 'open') not in ('delivered', 'cancelled');

    if v_active_shipments >= 1 then
      return jsonb_build_object(
        'success', false,
        'error', 'active_shipment_limit_exceeded',
        'active_shipment_limit', 1
      );
    end if;

    select count(*)
    into v_shipments_last_7_days
    from public.shipments s
    where s.owner_id = v_actor
      and s.created_at >= now() - interval '7 days';

    if v_shipments_last_7_days >= 5 then
      return jsonb_build_object(
        'success', false,
        'error', 'weekly_shipment_limit_exceeded',
        'weekly_shipment_limit', 5
      );
    end if;
  end if;

  select rp.base_price, rp.customer_price
  into v_base_amount, v_customer_amount
  from public.route_prices rp
  where rp.origin_city_id = p_origin_city_id
    and rp.destination_city_id = p_destination_city_id
    and rp.is_active = true
  order by rp.updated_at desc, rp.created_at desc
  limit 1;

  if v_base_amount is null or v_customer_amount is null then
    return jsonb_build_object(
      'success', false,
      'error', 'route_not_available'
    );
  end if;

  v_quote := public.calculate_payment_amount(v_base_amount, v_customer_amount);

  if coalesce((v_quote ->> 'success')::boolean, false) = false then
    return coalesce(v_quote, '{}'::jsonb) || jsonb_build_object(
      'success', false,
      'error', coalesce(v_quote ->> 'error', 'quote_error')
    );
  end if;

  loop
    v_attempts := v_attempts + 1;
    v_tracking_code := 'INTRA-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));

    exit when not exists (
      select 1
      from public.shipments s
      where s.tracking_code = v_tracking_code
    );

    if v_attempts >= 10 then
      return jsonb_build_object(
        'success', false,
        'error', 'tracking_code_generation_failed'
      );
    end if;
  end loop;

  insert into public.shipments (
    owner_id,
    origin_city_id,
    destination_city_id,
    kind,
    description,
    weight_kg,
    declared_value_cop,
    is_fragile,
    is_urgent,
    is_high_value,
    status,
    tracking_code
  ) values (
    v_actor,
    p_origin_city_id,
    p_destination_city_id,
    p_kind,
    btrim(p_description),
    p_weight_kg,
    p_declared_value_cop,
    coalesce(p_is_fragile, false),
    coalesce(p_is_urgent, false),
    coalesce(p_is_high_value, false),
    'open',
    v_tracking_code
  )
  returning id into v_shipment_id;

  insert into public.shipment_declarations (
    shipment_id,
    user_id,
    declaration_text,
    declaration_version,
    accepted_at,
    acceptance_flow,
    user_agent,
    ip_address,
    shipping_policy_version,
    shipping_policy_accepted_at,
    payment_policy_version,
    payment_policy_accepted_at,
    metadata
  ) values (
    v_shipment_id,
    v_actor,
    v_declaration_text,
    coalesce(nullif(btrim(p_declaration_version), ''), '1.0'),
    v_accepted_at,
    coalesce(nullif(btrim(p_acceptance_flow), ''), 'shipment_checkout'),
    nullif(btrim(coalesce(p_user_agent, '')), ''),
    coalesce(p_ip_address, v_ip_address),
    btrim(p_shipping_policy_version),
    v_accepted_at,
    btrim(p_payment_policy_version),
    v_accepted_at,
    jsonb_build_object(
      'verified_v1', v_is_verified_v1,
      'verification_status', v_verification_status,
      'declared_value_limit_cop', v_declared_value_limit,
      'weight_limit_kg', 10,
      'payment_policy_accepted', true
    )
  );

  v_external_reference := 'intra-shipment-' || v_shipment_id::text || '-' || gen_random_uuid()::text;

  insert into public.payments (
    shipment_id,
    user_id,
    amount,
    gross_amount,
    traveler_amount,
    intra_fee,
    gateway_fee_estimated,
    net_amount_received,
    currency,
    status,
    gateway_provider,
    gateway_status,
    payment_method,
    external_reference,
    metadata
  ) values (
    v_shipment_id,
    v_actor,
    coalesce((v_quote ->> 'amount')::numeric, 0),
    coalesce((v_quote ->> 'gross_amount')::numeric, 0),
    coalesce((v_quote ->> 'traveler_amount')::numeric, 0),
    coalesce((v_quote ->> 'intra_fee')::numeric, 0),
    coalesce((v_quote ->> 'gateway_fee_estimated')::numeric, 0),
    coalesce((v_quote ->> 'net_amount_received')::numeric, 0),
    coalesce(v_quote ->> 'currency', 'COP'),
    'pending',
    'wompi',
    'created',
    'wompi_widget',
    v_external_reference,
    jsonb_build_object(
      'source', 'shipment_rpc',
      'auto_release_hours', coalesce((v_quote ->> 'auto_release_hours')::integer, 48),
      'dispute_window_hours', coalesce((v_quote ->> 'dispute_window_hours')::integer, 24),
      'declaration_version', coalesce(nullif(btrim(p_declaration_version), ''), '1.0'),
      'shipping_policy_version', btrim(p_shipping_policy_version),
      'payment_policy_version', btrim(p_payment_policy_version),
      'tracking_code', v_tracking_code,
      'is_fragile', coalesce(p_is_fragile, false),
      'is_urgent', coalesce(p_is_urgent, false),
      'is_high_value', coalesce(p_is_high_value, false),
      'verified_v1', v_is_verified_v1
    )
  )
  returning id into v_payment_id;

  return jsonb_build_object(
    'success', true,
    'shipment_id', v_shipment_id,
    'payment_id', v_payment_id,
    'tracking_code', v_tracking_code,
    'verification_status', v_verification_status,
    'verified_v1', v_is_verified_v1,
    'quote', v_quote
  );
exception
  when others then
    return jsonb_build_object(
      'success', false,
      'error', 'unexpected_error',
      'message', SQLERRM
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_shipment_delivery(p_shipment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_match_id uuid;
  v_owner_id uuid;
  v_traveler_id uuid;
  v_payment public.payments;
  v_release_result jsonb;
begin
  if v_actor is null then
    raise exception 'No autenticado';
  end if;

  select m.id, s.owner_id, t.traveler_id
  into v_match_id, v_owner_id, v_traveler_id
  from public.matches m
  join public.shipments s on s.id = m.shipment_id
  join public.trips t on t.id = m.trip_id
  where m.shipment_id = p_shipment_id
    and m.status = 'accepted'
  limit 1;

  if v_match_id is null then
    raise exception 'No existe un match accepted para este shipment';
  end if;

  if v_owner_id is null then
    raise exception 'No se encontró el owner del shipment';
  end if;

  if v_actor <> v_owner_id then
    raise exception 'No autorizado: solo el cliente puede confirmar la recepción';
  end if;

  select *
  into v_payment
  from public.payments
  where shipment_id = p_shipment_id
  order by created_at desc
  limit 1
  for update;

  if v_payment.id is null then
    raise exception 'payment_not_found';
  end if;

  if v_payment.status <> 'held' then
    raise exception 'payment_not_held';
  end if;

  if v_payment.dispute_status = 'open' then
    raise exception 'match_in_dispute';
  end if;

  if v_payment.traveler_delivered_at is null then
    raise exception 'traveler_delivery_not_reported';
  end if;

  update public.shipments
  set status = 'delivered'
  where id = p_shipment_id
    and status = 'in_transit';

  if not found then
    raise exception 'El shipment no estaba en in_transit';
  end if;

  update public.matches
  set status = 'completed'
  where id = v_match_id
    and status = 'accepted';

  update public.payments
  set
    delivered_at = now(),
    auto_release_at = null,
    updated_at = now()
  where id = v_payment.id;

  v_release_result := public.release_payment(v_payment.id, 'customer_received');

  if coalesce((v_release_result ->> 'success')::boolean, false) is not true then
    raise exception '%', coalesce(v_release_result ->> 'error', 'release_payment_failed');
  end if;

  insert into public.notifications (
    user_id,
    type,
    title,
    message,
    related_match_id
  )
  select
    v_traveler_id,
    'delivery_confirmed',
    'El cliente confirmó la recepción',
    'El cliente confirmó que recibió el paquete y el pago fue liberado.',
    v_match_id
  where v_traveler_id is not null
    and v_traveler_id <> v_actor
    and not exists (
      select 1
      from public.notifications n
      where n.user_id = v_traveler_id
        and n.type = 'delivery_confirmed'
        and n.related_match_id = v_match_id
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.close_trip(p_trip_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_trip public.trips;
  v_cancelled_match record;
  v_cancelled_match_ids uuid[] := '{}'::uuid[];
  v_cancelled_count integer := 0;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'No autenticado');
  end if;

  select *
  into v_trip
  from public.trips
  where id = p_trip_id
  for update;

  if v_trip.id is null then
    return jsonb_build_object('success', false, 'error', 'Viaje no encontrado');
  end if;

  if v_trip.traveler_id <> v_actor then
    return jsonb_build_object('success', false, 'error', 'No autorizado');
  end if;

  if v_trip.status not in ('open', 'full') then
    return jsonb_build_object('success', false, 'error', 'Este viaje ya no puede cerrarse');
  end if;

  update public.trips
  set status = 'closed'
  where id = p_trip_id;

  for v_cancelled_match in
    update public.matches m
    set status = 'cancelled'
    where m.trip_id = p_trip_id
      and m.status = 'pending'
    returning m.id, m.shipment_id
  loop
    v_cancelled_count := v_cancelled_count + 1;
    v_cancelled_match_ids := array_append(v_cancelled_match_ids, v_cancelled_match.id);

    insert into public.notifications (
      user_id,
      type,
      title,
      message,
      related_match_id
    )
    select
      s.owner_id,
      'match_cancelled',
      'El viaje ya no recibe solicitudes',
      'El viajero cerró su viaje y esta solicitud pendiente fue cancelada.',
      v_cancelled_match.id
    from public.shipments s
    where s.id = v_cancelled_match.shipment_id;
  end loop;

  return jsonb_build_object(
    'success', true,
    'trip_id', p_trip_id,
    'cancelled_count', v_cancelled_count,
    'cancelled_match_ids', to_jsonb(v_cancelled_match_ids)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_request_ip()
 RETURNS inet
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_headers jsonb := nullif(current_setting('request.headers', true), '')::jsonb;
  v_ip_text text;
begin
  v_ip_text := nullif(
    btrim(
      coalesce(
        v_headers ->> 'cf-connecting-ip',
        split_part(v_headers ->> 'x-forwarded-for', ',', 1),
        v_headers ->> 'x-real-ip'
      )
    ),
    ''
  );

  if v_ip_text is null then
    return null;
  end if;

  begin
    return v_ip_text::inet;
  exception
    when others then
      return null;
  end;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_policy_acceptance(p_policy_key text, p_policy_version text, p_acceptance_flow text DEFAULT 'manual'::text, p_user_agent text DEFAULT NULL::text, p_ip_address inet DEFAULT NULL::inet, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'not_authenticated');
  end if;

  if p_policy_key is null or p_policy_key not in (
    'terms-conditions',
    'privacy-policy'
  ) then
    return jsonb_build_object('success', false, 'error', 'invalid_policy_key');
  end if;

  if nullif(btrim(coalesce(p_policy_version, '')), '') is null then
    return jsonb_build_object('success', false, 'error', 'invalid_policy_version');
  end if;

  insert into public.user_policy_acceptances (
    user_id,
    policy_key,
    policy_version,
    acceptance_flow,
    user_agent,
    ip_address,
    metadata
  )
  values (
    v_actor,
    p_policy_key,
    btrim(p_policy_version),
    coalesce(nullif(btrim(p_acceptance_flow), ''), 'manual'),
    nullif(btrim(coalesce(p_user_agent, '')), ''),
    p_ip_address,
    coalesce(p_metadata, '{}'::jsonb)
  );

  return jsonb_build_object('success', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.accept_match(p_match_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_trip_id uuid;
  v_shipment_id uuid;
  v_owner_id uuid;
  v_traveler_id uuid;
  v_capacity numeric;
  v_used_kg numeric;
  v_new_kg numeric;
  v_hold_result jsonb;
begin
  if v_actor is null then
    raise exception 'No autenticado';
  end if;

  select m.trip_id, m.shipment_id
  into v_trip_id, v_shipment_id
  from public.matches m
  where m.id = p_match_id
  for update;

  if v_trip_id is null then
    raise exception 'Match no existe';
  end if;

  select s.owner_id
  into v_owner_id
  from public.shipments s
  where s.id = v_shipment_id;

  if v_owner_id is null then
    raise exception 'Shipment no existe';
  end if;

  if v_actor <> v_owner_id then
    raise exception 'No autorizado (solo el cliente puede aceptar)';
  end if;

  select t.capacity_kg, t.traveler_id
  into v_capacity, v_traveler_id
  from public.trips t
  where t.id = v_trip_id
  for update;

  if v_traveler_id is null then
    raise exception 'Trip no existe o no tiene traveler';
  end if;

  select coalesce(s.weight_kg, 0)
  into v_new_kg
  from public.shipments s
  where s.id = v_shipment_id;

  select coalesce(sum(coalesce(s2.weight_kg, 0)), 0)
  into v_used_kg
  from public.matches m2
  join public.shipments s2 on s2.id = m2.shipment_id
  where m2.trip_id = v_trip_id
    and m2.status = 'accepted';

  if v_capacity is not null and (v_used_kg + v_new_kg) > v_capacity then
    raise exception 'Capacidad insuficiente: usado=%, nuevo=%, capacidad=%',
      v_used_kg, v_new_kg, v_capacity;
  end if;

  update public.matches
  set status = 'accepted'
  where id = p_match_id
    and status = 'pending';

  if not found then
    raise exception 'Match no estaba en pending (ya fue procesado)';
  end if;

  update public.shipments
  set status = 'matched'
  where id = v_shipment_id
    and status = 'open';

  if not found then
    raise exception 'El shipment no estaba en open';
  end if;

  if v_capacity is null then
    update public.trips
    set status = 'open'
    where id = v_trip_id
      and status <> 'cancelled';
  else
    if (v_used_kg + v_new_kg) >= v_capacity then
      update public.trips
      set status = 'full'
      where id = v_trip_id
        and status <> 'cancelled';
    else
      update public.trips
      set status = 'open'
      where id = v_trip_id
        and status <> 'cancelled';
    end if;
  end if;

  v_hold_result := public.attach_payment_hold_to_match(
    p_match_id,
    v_shipment_id,
    v_traveler_id
  );

  if coalesce((v_hold_result ->> 'success')::boolean, false) = false then
    raise exception '%', coalesce(v_hold_result ->> 'error', 'no_active_payment');
  end if;

  insert into public.notifications (
    user_id,
    type,
    title,
    message,
    related_match_id
  )
  select
    v_traveler_id,
    'match_accepted',
    'Tu solicitud fue aceptada',
    'El cliente aceptó tu solicitud de transporte.',
    p_match_id
  where not exists (
    select 1
    from public.notifications n
    where n.user_id = v_traveler_id
      and n.type = 'match_accepted'
      and n.related_match_id = p_match_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.request_match(p_shipment_id uuid, p_trip_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_match_id uuid;
  v_active_matches integer := 0;
  v_is_verified_v1 boolean := false;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'not_authenticated');
  end if;

  if p_shipment_id is null or p_trip_id is null then
    return jsonb_build_object('success', false, 'error', 'match_route_required');
  end if;

  v_is_verified_v1 := public.is_user_verified_v1(v_actor);

  if not v_is_verified_v1 then
    select count(*)
    into v_active_matches
    from public.matches m
    join public.shipments s on s.id = m.shipment_id
    where m.requester_id = v_actor
      and m.status in ('pending', 'accepted')
      and coalesce(s.status, 'open') not in ('delivered', 'cancelled');

    if v_active_matches >= 1 then
      return jsonb_build_object(
        'success', false,
        'error', 'active_match_limit_exceeded',
        'active_match_limit', 1
      );
    end if;
  end if;

  if not exists (
    select 1
    from public.trips t
    where t.id = p_trip_id
      and t.traveler_id = v_actor
      and t.status in ('open', 'full')
  ) then
    return jsonb_build_object('success', false, 'error', 'trip_not_available');
  end if;

  if not exists (
    select 1
    from public.shipments s
    where s.id = p_shipment_id
      and s.owner_id <> v_actor
      and s.status = 'open'
      and public.is_shipment_payment_ready(s.id)
  ) then
    return jsonb_build_object('success', false, 'error', 'shipment_not_available');
  end if;

  insert into public.matches (
    shipment_id,
    trip_id,
    requester_id,
    status
  ) values (
    p_shipment_id,
    p_trip_id,
    v_actor,
    'pending'
  )
  returning id into v_match_id;

  return jsonb_build_object('success', true, 'match_id', v_match_id);
exception
  when unique_violation then
    return jsonb_build_object('success', false, 'error', 'match_already_requested');
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_shipment_in_transit(p_shipment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_match_id uuid;
  v_trip_id uuid;
  v_traveler_id uuid;
  v_owner_id uuid;
  v_payment_id uuid;
begin
  if v_actor is null then
    raise exception 'No autenticado';
  end if;

  select m.id, m.trip_id, s.owner_id
  into v_match_id, v_trip_id, v_owner_id
  from public.matches m
  join public.shipments s on s.id = m.shipment_id
  where m.shipment_id = p_shipment_id
    and m.status = 'accepted'
  limit 1;

  if v_match_id is null then
    raise exception 'No existe un match accepted para este shipment';
  end if;

  select t.traveler_id
  into v_traveler_id
  from public.trips t
  where t.id = v_trip_id;

  if v_traveler_id is null then
    raise exception 'No se encontró el viajero del trip';
  end if;

  if v_actor <> v_traveler_id then
    raise exception 'No autorizado: solo el viajero puede marcar en tránsito';
  end if;

  select p.id
  into v_payment_id
  from public.payments p
  where p.shipment_id = p_shipment_id
    and p.status = 'held'
  order by p.created_at desc
  limit 1;

  if v_payment_id is null then
    raise exception 'payment_not_held';
  end if;

  update public.shipments
  set status = 'in_transit'
  where id = p_shipment_id
    and status = 'matched';

  if not found then
    raise exception 'El shipment no estaba en matched';
  end if;

  insert into public.notifications (
    user_id,
    type,
    title,
    message,
    related_match_id
  )
  select
    v_owner_id,
    'shipment_in_transit',
    'Tu envío está en camino',
    'El viajero marcó tu envío como en tránsito.',
    v_match_id
  where v_owner_id is not null
    and v_owner_id <> v_actor
    and not exists (
      select 1
      from public.notifications n
      where n.user_id = v_owner_id
        and n.type = 'shipment_in_transit'
        and n.related_match_id = v_match_id
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_payout_operational_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_type text;
  v_title text;
  v_message text;
begin
  if tg_op = 'INSERT' then
    perform public.create_operational_notification(
      new.traveler_user_id,
      'payout_requested',
      'Retiro solicitado',
      'Tu solicitud de retiro quedo registrada.',
      null,
      'payout:' || new.id::text || ':requested',
      true
    );

    return new;
  end if;

  if coalesce(old.status, '') = coalesce(new.status, '') then
    return new;
  end if;

  v_type := case new.status
    when 'approved' then 'payout_approved'
    when 'rejected' then 'payout_rejected'
    when 'paid' then 'payout_paid'
    else null
  end;

  if v_type is null then
    return new;
  end if;

  v_title := case new.status
    when 'approved' then 'Retiro aprobado'
    when 'rejected' then 'Retiro rechazado'
    when 'paid' then 'Retiro pagado'
    else 'Retiro actualizado'
  end;

  v_message := case new.status
    when 'approved' then 'Tu retiro fue aprobado para pago manual.'
    when 'rejected' then 'Tu solicitud de retiro fue rechazada.'
    when 'paid' then 'Tu retiro fue marcado como pagado.'
    else 'Tu retiro fue actualizado.'
  end;

  perform public.create_operational_notification(
    new.traveler_user_id,
    v_type,
    v_title,
    v_message,
    null,
    'payout:' || new.id::text || ':' || new.status,
    true
  );

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_shipment_delivered(p_shipment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_match_id uuid;
  v_trip_id uuid;
  v_traveler_id uuid;
  v_owner_id uuid;
  v_payment public.payments;
  v_config public.fee_configs;
begin
  if v_actor is null then
    raise exception 'No autenticado';
  end if;

  select m.id, m.trip_id, s.owner_id
  into v_match_id, v_trip_id, v_owner_id
  from public.matches m
  join public.shipments s on s.id = m.shipment_id
  where m.shipment_id = p_shipment_id
    and m.status = 'accepted'
  limit 1;

  if v_match_id is null then
    raise exception 'No existe un match accepted para este shipment';
  end if;

  select t.traveler_id
  into v_traveler_id
  from public.trips t
  where t.id = v_trip_id;

  if v_traveler_id is null then
    raise exception 'No se encontró el viajero del trip';
  end if;

  if v_actor <> v_traveler_id then
    raise exception 'No autorizado: solo el viajero puede marcar entregado';
  end if;

  select *
  into v_payment
  from public.payments
  where shipment_id = p_shipment_id
  order by created_at desc
  limit 1
  for update;

  if v_payment.id is null then
    raise exception 'payment_not_found';
  end if;

  if v_payment.status <> 'held' then
    raise exception 'payment_not_held';
  end if;

  if v_payment.dispute_status = 'open' then
    raise exception 'match_in_dispute';
  end if;

  if v_payment.traveler_delivered_at is not null then
    raise exception 'delivery_already_reported';
  end if;

  select *
  into v_config
  from public.fee_configs
  where is_active = true
  order by updated_at desc, created_at desc
  limit 1;

  update public.payments
  set
    traveler_delivered_at = now(),
    auto_release_at = now() + make_interval(hours => coalesce(v_config.auto_release_hours, 48)),
    updated_at = now()
  where id = v_payment.id;

  insert into public.notifications (
    user_id,
    type,
    title,
    message,
    related_match_id
  )
  select
    v_owner_id,
    'delivery_reported',
    'El viajero reportó la entrega',
    'El viajero marcó el paquete como entregado. Confirma si ya lo recibiste o abre disputa si algo salió mal.',
    v_match_id
  where v_owner_id is not null
    and v_owner_id <> v_actor
    and not exists (
      select 1
      from public.notifications n
      where n.user_id = v_owner_id
        and n.type = 'delivery_reported'
        and n.related_match_id = v_match_id
    );
end;
$function$
